using System.Text.Json;using FluentValidation;
namespace EventLensAI.Application.Features.Photos.Templates;
public sealed class UpsertPhotoTemplateRequestValidator:AbstractValidator<UpsertPhotoTemplateRequest>{public UpsertPhotoTemplateRequestValidator(){RuleFor(x=>x.OrganizationId).NotEmpty();RuleFor(x=>x.Name).NotEmpty().MaximumLength(150);RuleFor(x=>x.Description).MaximumLength(1000);RuleFor(x=>x.Width).InclusiveBetween(128,8192);RuleFor(x=>x.Height).InclusiveBetween(128,8192);RuleFor(x=>x.Resolution).InclusiveBetween(72,600);RuleFor(x=>x.AspectRatio).Matches(@"^\d+:\d+$");RuleFor(x=>x.BackgroundColor).Matches("^#[0-9A-Fa-f]{6}$");RuleFor(x=>x.BackgroundImage).Must(x=>x is null||x.StartsWith("asset:")).WithMessage("Background must be an approved asset reference.");RuleForEach(x=>x.Elements).ChildRules(e=>{e.RuleFor(x=>x.Width).GreaterThan(0);e.RuleFor(x=>x.Height).GreaterThan(0);e.RuleFor(x=>x.PositionX).GreaterThanOrEqualTo(0);e.RuleFor(x=>x.PositionY).GreaterThanOrEqualTo(0);e.RuleFor(x=>x.StyleConfiguration).Must(IsJson);});RuleFor(x=>x.Elements).Must(x=>x.Count<=100); }static bool IsJson(string x){try{JsonDocument.Parse(x);return true;}catch{return false;}}}
public sealed class RenderTemplateRequestValidator:AbstractValidator<RenderTemplateRequest>{public RenderTemplateRequestValidator(){RuleFor(x=>x.OrganizationId).NotEmpty();RuleFor(x=>x.PhotoDataUrls).Must(x=>x.Count is>=1 and<=12);RuleForEach(x=>x.PhotoDataUrls).Must(x=>x.StartsWith("data:image/jpeg;base64,")||x.StartsWith("data:image/png;base64,")).WithMessage("Only bounded JPEG or PNG data URLs are accepted.");RuleForEach(x=>x.PhotoDataUrls).MaximumLength(15_000_000);RuleFor(x=>x.EventName).MaximumLength(200);RuleFor(x=>x.GuestName).MaximumLength(200);RuleFor(x=>x.QrContent).MaximumLength(2048);}}
